@Claims.NANUQ.repeated_label_anchor : ∀ {V : Type u_1} {E : Type u_2} {X : Type u_3} [inst : Fintype V]
  [inst_1 : Fintype E] [inst_2 : Fintype X] [inst_3 : DecidableEq V] (N : Nanuq.Source.RootedBinary V E X)
  (v : Fin 4 → X), N.actualTupleAnchor v = ∑ b, N.actualBlobTupleAnchor ↑b ⋯ v

@Claims.NANUQ.actual_opened_curve_subset : ∀ {V : Type u_1} {E : Type u_2} {X : Type u_3} {P : Type u_4}
  [inst : TopologicalSpace P] [inst_1 : Fintype V] [inst_2 : Fintype E] [inst_3 : Fintype X] [inst_4 : DecidableEq V]
  (N : Nanuq.Source.RootedBinary V E X) (D : N.graph.CurveDrawing)
  (hleaf : ∀ (e : E), N.graph.IsHybrid (N.graph.source e) → ∃ x, N.graph.target e = N.leaf x),
  Set.range (N.actualOpenedCurveDrawing D hleaf).point ∪ ⋃ e, Set.range ⇑((N.actualOpenedCurveDrawing D hleaf).arc e) ⊆
    Set.range D.point ∪ ⋃ e, Set.range ⇑(D.arc e)

@Claims.NANUQ.original_curve_adapter_roundtrip : ∀ {V : Type u_1} {E : Type u_2} {G : Nanuq.Source.EdgeGraph V E}
  (D : G1OuterLabelledMultigraphCurves.PlanarCurves G),
  G1OuterLabelledMultigraphCurves.ofCurveDrawing D.toCurveDrawing = D

@Nanuq.Source.RootedBinary.rawRho_witness_symmetric : ∀ {V : Type u_1} {E : Type u_2} [inst : Fintype V]
  [inst_1 : Fintype E] [inst_2 : DecidableEq V] {n : ℕ} (N : Nanuq.Source.RootedBinary V E (Fin n)),
  Nanuq.Composition.WitnessSymmetric N.rawRho

@Nanuq.Source.RootedBinary.rawRho_endpoint_symmetric : ∀ {V : Type u_1} {E : Type u_2} [inst : Fintype V]
  [inst_1 : Fintype E] [inst_2 : DecidableEq V] {n : ℕ} (N : Nanuq.Source.RootedBinary V E (Fin n)),
  Nanuq.Weighted.QuartetEndpointSymmetric N.rawRho

@Nanuq.Source.RootedBinary.rawNanuq_symmetric : ∀ {V : Type u_1} {E : Type u_2} [inst : Fintype V] [inst_1 : Fintype E]
  [inst_2 : DecidableEq V] {n : ℕ} (N : Nanuq.Source.RootedBinary V E (Fin n)) (x y : Fin n),
  N.rawNanuq x y = N.rawNanuq y x

@Nanuq.Source.RootedBinary.rawNanuq_positive : ∀ {V : Type u_1} {E : Type u_2} [inst : Fintype V] [inst_1 : Fintype E]
  [inst_2 : DecidableEq V] {n : ℕ} (N : Nanuq.Source.RootedBinary V E (Fin n)),
  3 ≤ n → ∀ (x y : Fin n), x ≠ y → 0 < N.rawNanuq x y

@Nanuq.Source.RootedBinary.rawNanuq_ordered_formula : ∀ {V : Type u_1} {E : Type u_2} [inst : Fintype V]
  [inst_1 : Fintype E] [inst_2 : DecidableEq V] {n : ℕ} (N : Nanuq.Source.RootedBinary V E (Fin n)) (x y : Fin n),
  N.rawNanuq x y = Nanuq.Composition.sourceDistance (Nanuq.Composition.maskedRho N.rawRho) x y

@Nanuq.Source.RootedBinary.actualQuartetData_witness_symmetric : ∀ {V : Type u_1} {E : Type u_2} {n : ℕ}
  [inst : Fintype V] [inst_1 : Fintype E] [inst_2 : DecidableEq V] (N : Nanuq.Source.RootedBinary V E (Fin n)),
  Nanuq.Composition.WitnessSymmetric N.actualQuartetData

@Nanuq.Source.RootedBinary.actual_weightedNanuq_eq_anchor : ∀ {V : Type u_1} {E : Type u_2} {n : ℕ} [inst : Fintype V]
  [inst_1 : Fintype E] [inst_2 : DecidableEq V] (N : Nanuq.Source.RootedBinary V E (Fin n)) (m : Fin n → ℚ)
  (x y : Fin n), Nanuq.Weighted.weightedNanuq N.actualQuartetData m x y = N.actualWeightedAnchorDistance m x y
